100	std::pair<std::string, std::string> ExtractParentDirAndFileName(const std::string &abs_path) {
101	  if (abs_path.empty()) {
102	    return {"", ""};
103	  }
104	  size_t last_slash = abs_path.find_last_of('/');
105	  if (last_slash == std::string::npos) {
106	    return {"", abs_path};
107	  }
108	  if (last_slash == 0) {
109	    return {"/", abs_path.substr(1)};
110	  }
111	  return {abs_path.substr(0, last_slash + 1), abs_path.substr(last_slash + 1)};
112	}
113	
114	void CloseMemFd(int32_t &fd) {
115	  if (fd >= 0) {
116	    (void)mmClose(fd);
117	    fd = -1;
118	  }
119	}
120	
121	ge::Status CreateSoMemFd(const std::string &file_name, const void *data, const size_t size, std::string &fd_path,
122	                         int32_t &fd) {
123	  GE_ASSERT_NOTNULL(data);
124	  GE_ASSERT_TRUE(size > 0U);
125	  CloseMemFd(fd);
126	
127	  const auto short_name = ExtractParentDirAndFileName(file_name).second;
128	  fd = static_cast<int32_t>(syscall(__NR_memfd_create, short_name.c_str(), 0));
129	  GE_ASSERT_TRUE(fd >= 0, "[OM2][Create][MemFd] Failed, file=%s", file_name.c_str());
130	  GE_DISMISSABLE_GUARD(memfd_cleanup, [&fd]() { CloseMemFd(fd); });
131	
132	  const auto write_count = mmWrite(fd, const_cast<void *>(data), size);
133	  GE_ASSERT_TRUE(write_count == static_cast<mmSsize_t>(size),
134	                 "[OM2][Write][MemFd] Failed, file=%s, size=%zu, write_count=%lld", file_name.c_str(), size,
135	                 static_cast<long long>(write_count));
136	  GE_ASSERT_TRUE(lseek(fd, 0, SEEK_SET) >= 0, "[OM2][Seek][MemFd] Failed, file=%s", file_name.c_str());
137	
138	  fd_path = "/proc/" + std::to_string(getpid()) + "/fd/" + std::to_string(fd);
139	  GE_DISMISS_GUARD(memfd_cleanup);
140	  return ge::SUCCESS;
141	}
