147	ge::Status ExtractEntryToString(const ge::RAIIZipArchive &archive, const std::string &entry_name, std::string &out) {
148	  size_t buffer_size{0U};
149	  const auto buffer = archive.ExtractToMem(entry_name, buffer_size);
150	  GE_ASSERT_NOTNULL(buffer, "[OM2] Failed to extract entry %s", entry_name.c_str());
151	  GE_ASSERT_TRUE(buffer_size > 0U, "[OM2] Empty archive entry %s", entry_name.c_str());
152	  out.assign(reinterpret_cast<const char *>(buffer.get()), buffer_size);
153	  return ge::SUCCESS;
154	}
