166	ge::Status ParseTensorDescFromJson(const ge::JsonFile &json_file, ge::Om2TensorDesc &desc) {
167	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "name", [&](const std::string &v) { desc.SetName(v); });
168	  ge::JsonFile::TryGetAndApply<std::vector<int64_t>>(json_file, "shape",
169	                                                     [&](const std::vector<int64_t> &v) { desc.SetShape(v); });
170	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "data_type", [&](const std::string &v) {
171	    desc.SetDataType(ge::TypeUtilsInner::SerialStringToDataType(v));
172	  });
173	  ge::JsonFile::TryGetAndApply<std::string>(
174	      json_file, "format", [&](const std::string &v) { desc.SetFormat(ge::TypeUtilsInner::SerialStringToFormat(v)); });
175	  ge::JsonFile::TryGetAndApply<size_t>(json_file, "size", [&](const size_t &v) { desc.SetSize(v); });
176	  ge::JsonFile::TryGetAndApply<std::vector<std::pair<int64_t, int64_t>>>(
177	      json_file, "shape_range", [&](const std::vector<std::pair<int64_t, int64_t>> &v) { desc.SetShapeRange(v); });
178	  return ge::SUCCESS;
179	}
