181	ge::Status ParseOpAttrMapJson(const uint8_t *data, size_t data_size,
182	                              std::map<std::string, std::map<std::string, std::string>> &op_attr_map) {
183	  try {
184	    const auto json_obj = ge::JsonFile::json::parse(data, data + data_size);
185	    if (!json_obj.is_object()) {
186	      GELOGW("[OM2] op_attr.json root is not an object");
187	      return ge::FAILED;
188	    }
189	
190	    for (auto &[op_name, attrs] : json_obj.items()) {
191	      if (!attrs.is_object()) {
192	        GELOGW("[OM2] op_attr for %s is not an object", op_name.c_str());
193	        continue;
194	      }
195	      std::map<std::string, std::string> op_attrs;
196	      for (auto &[attr_name, value] : attrs.items()) {
197	        if (value.is_string()) {
198	          op_attrs[attr_name] = value.get<std::string>();
199	        } else {
200	          op_attrs[attr_name] = value.dump();
201	        }
202	      }
203	      op_attr_map[op_name] = op_attrs;
204	    }
205	    return ge::SUCCESS;
206	  } catch (const ge::JsonFile::json::exception &e) {
207	    GELOGE(ge::FAILED, "[OM2] Failed to parse op_attr.json: %s", e.what());
208	    return ge::FAILED;
209	  }
210	}
