229	ge::Status DeserializeConstantsConfigEntry(const ge::RAIIZipArchive &archive, const std::string &entry,
230	                                           gert::Om2ModelData &model_data) {
231	  size_t buff_size = 0U;
232	  auto buff_data = archive.ExtractToMem(entry, buff_size);
233	  GE_ASSERT_NOTNULL(buff_data, "[OM2] Failed to extract %s", entry.c_str());
234	  GE_ASSERT_TRUE(buff_size > 0U);
235	  const ge::JsonFile json_file(buff_data.get(), buff_size);
236	  GE_ASSERT_TRUE(json_file.IsValid(), "[OM2] Invalid constants config JSON from entry %s", entry.c_str());
237	
238	  size_t internal_weight_size{0U};
239	  (void)json_file.Get("internal_weight_size", internal_weight_size);
240	  model_data.constants_data.internal_weight_size = internal_weight_size;
241	
242	  ge::JsonFile::json consts_json;
243	  if (json_file.Get("consts", consts_json) && consts_json.is_object()) {
244	    for (auto &[key, val] : consts_json.items()) {
245	      (void)key;
246	      const ge::JsonFile val_file(val);
247	      ge::Om2ConstMeta meta;
248	      (void)val_file.Get("index", meta.index);
249	      (void)val_file.Get("type", meta.type);
250	      (void)val_file.Get("file_name", meta.file_name);
251	      (void)val_file.Get("file_path", meta.file_path);
252	      (void)val_file.Get("offset", meta.offset);
253	      (void)val_file.Get("size", meta.size);
254	      (void)val_file.Get("op_name", meta.op_name);
255	      (void)model_data.constants_data.consts.emplace_back(std::move(meta));
256	    }
257	  }
258	  return ge::SUCCESS;
259	}
