261	ge::Status ParseTransNodeFromJson(const ge::JsonFile &json_file, gert::RTTransNodeInfo &node_info) {
262	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "node_type",
263	                                            [&](const std::string &v) { node_info.node_type = v; });
264	  ge::JsonFile input_json;
265	  if (json_file.Get("input", input_json)) {
266	    GE_ASSERT_SUCCESS(ParseTensorDescFromJson(input_json, node_info.input));
267	  }
268	  ge::JsonFile output_json;
269	  if (json_file.Get("output", output_json)) {
270	    GE_ASSERT_SUCCESS(ParseTensorDescFromJson(output_json, node_info.output));
271	  }
272	  return ge::SUCCESS;
273	}
