278	  ge::JsonFile src_tensor_desc_json;
279	  if (json_file.Get("src_tensor_desc", src_tensor_desc_json)) {
280	    GE_ASSERT_SUCCESS(ParseTensorDescFromJson(src_tensor_desc_json, copy_info.src_tensor_desc));
281	  }
282	  return ge::SUCCESS;
