284	
285	ge::Status ParseVarEntryFromJson(const ge::JsonFile &json_file, const uint8_t *weight_data, size_t weight_data_size,
286	                                 gert::RTVarEntry &entry) {
287	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "var_name", [&](const std::string &v) { entry.var_name = v; });
288	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "var_key", [&](const std::string &v) { entry.var_key = v; });
289	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "op_type", [&](const std::string &v) { entry.op_type = v; });
290	  ge::JsonFile::TryGetAndApply<uint64_t>(json_file, "logic_addr", [&](const uint64_t &v) { entry.logic_addr = v; });
291	  ge::JsonFile::TryGetAndApply<uint64_t>(json_file, "size", [&](const uint64_t &v) { entry.size = v; });
292	  ge::JsonFile::TryGetAndApply<uint32_t>(json_file, "memory_type", [&](const uint32_t &v) { entry.memory_type = v; });
293	  ge::JsonFile::TryGetAndApply<uint32_t>(json_file, "changed_graph_id",
294	                                         [&](const uint32_t &v) { entry.changed_graph_id = v; });
295	  ge::JsonFile::TryGetAndApply<uint32_t>(json_file, "allocated_graph_id",
296	                                         [&](const uint32_t &v) { entry.allocated_graph_id = v; });
297	
298	  ge::JsonFile tensor_desc_json;
299	  if (json_file.Get("tensor_desc", tensor_desc_json)) {
300	    GE_ASSERT_SUCCESS(ParseTensorDescFromJson(tensor_desc_json, entry.tensor_desc));
301	  }
302	
303	  ge::JsonFile::json trans_road_json;
304	  if (json_file.Get("trans_road", trans_road_json) && trans_road_json.is_array()) {
305	    for (const auto &node_json : trans_road_json) {
306	      gert::RTTransNodeInfo node_info;
307	      GE_ASSERT_SUCCESS(ParseTransNodeFromJson(ge::JsonFile(node_json), node_info));
308	      entry.trans_road.emplace_back(std::move(node_info));
309	    }
310	  }
311	
312	  ge::JsonFile copy_info_json;
313	  if (json_file.Get("copy_info", copy_info_json)) {
314	    GE_ASSERT_SUCCESS(ParseCopyInfoFromJson(copy_info_json, entry.copy_info));
315	  }
316	
317	  size_t init_data_offset = 0U;
318	  size_t init_data_size = 0U;
319	  (void)json_file.Get("init_data_offset", init_data_offset);
320	  (void)json_file.Get("init_data_size", init_data_size);
321	  if (init_data_size > 0U) {
322	    const bool is_init_data_valid =
323	        (init_data_offset <= weight_data_size) && (init_data_size <= (weight_data_size - init_data_offset));
324	    if (!is_init_data_valid) {
325	      GELOGW("[OM2][Var] Invalid or missing init data for var=%s, skip init_data.", entry.var_name.c_str());
326	    } else {
327	      entry.init_data.assign(weight_data + init_data_offset, weight_data + init_data_offset + init_data_size);
328	    }
329	  }
330	  return ge::SUCCESS;
331	}
332	
333	ge::Status ParseVarMetaFromJson(const ge::JsonFile &json_file, ge::Om2VarMeta &meta) {
334	  ge::JsonFile::TryGetAndApply<size_t>(json_file, "index", [&](const size_t &v) { meta.index = v; });
335	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "var_name", [&](const std::string &v) { meta.var_name = v; });
336	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "op_type", [&](const std::string &v) { meta.op_type = v; });
337	  ge::JsonFile::TryGetAndApply<std::string>(json_file, "op_name", [&](const std::string &v) { meta.op_name = v; });
338	
339	  ge::JsonFile tensor_desc_json;
340	  if (json_file.Get("tensor_desc", tensor_desc_json)) {
341	    GE_ASSERT_SUCCESS(ParseTensorDescFromJson(tensor_desc_json, meta.tensor_desc));
342	  }
343	  return ge::SUCCESS;
344	}
345	
346	ge::Status DeserializeVarResourceEntry(const ge::RAIIZipArchive &archive, const std::string &entry,
347	                                       gert::Om2ModelData &model_data) {
348	  size_t buff_size = 0U;
349	  auto buff_data = archive.ExtractToMem(entry, buff_size);
350	  GE_ASSERT_NOTNULL(buff_data, "[OM2] Failed to extract %s", entry.c_str());
351	  GE_ASSERT_TRUE(buff_size > 0U);
352	  const ge::JsonFile json_file(buff_data.get(), buff_size);
353	  GE_ASSERT_TRUE(json_file.IsValid(), "[OM2] Invalid var_resource.json");
354	
355	  const std::string weight_entry = ExtractParentDirAndFileName(entry).first + "var_weight_data";
356	  size_t weight_data_size = 0U;
357	  ge::ReadonlyByteBuffer weight_data(nullptr, ge::ConditionalDeleter{false});
358	  if (archive.HasEntry(weight_entry)) {
