407	ge::Status DeserializeModelMetaEntry(const ge::RAIIZipArchive &archive, const std::string &entry,
408	                                     gert::Om2ModelData &model_data) {
409	  size_t buff_size = 0U;
410	  auto buff_data = archive.ExtractToMem(entry, buff_size);
411	  GE_ASSERT_NOTNULL(buff_data, "[OM2] Failed to extract %s", entry.c_str());
412	  GE_ASSERT_TRUE(buff_size > 0U);
413	  const ge::JsonFile json_file(buff_data.get(), buff_size);
414	  GE_ASSERT_TRUE(json_file.IsValid(), "[OM2] Invalid model_meta.json");
415	
416	  ge::JsonFile::json inputs_json;
417	  if (json_file.Get("inputs", inputs_json) && inputs_json.is_array()) {
418	    for (const auto &input_json : inputs_json) {
419	      const ge::JsonFile input_file(input_json);
420	      std::vector<int64_t> shape_v2;
421	      GE_ASSERT_TRUE(input_file.Get("shape_v2", shape_v2), "[OM2] input shape_v2 not found in model_meta.json");
422	      ge::Om2TensorDesc desc;
423	      GE_ASSERT_SUCCESS(ParseTensorDescFromJson(input_file, desc));
424	      model_data.model_meta.input_desc.emplace_back(desc);
425	      ge::Om2TensorDesc desc_v2 = desc;
426	      desc_v2.SetShape(shape_v2);
427	      model_data.model_meta.input_desc_v2.emplace_back(desc_v2);
428	      std::vector<int64_t> origin_input_dims;
429	      if (input_file.Get("origin_input_dims", origin_input_dims)) {
430	        model_data.model_meta.origin_input_dims.emplace_back(std::move(origin_input_dims));
431	      } else {
432	        (void)model_data.model_meta.origin_input_dims.emplace_back(desc.GetShape());
433	      }
434	    }
435	  }
436	
437	  ge::JsonFile::json outputs_json;
438	  if (json_file.Get("outputs", outputs_json) && outputs_json.is_array()) {
439	    for (const auto &output_json : outputs_json) {
440	      const ge::JsonFile output_file(output_json);
441	      ge::Om2TensorDesc desc;
442	      GE_ASSERT_SUCCESS(ParseTensorDescFromJson(output_file, desc));
443	      model_data.model_meta.output_desc.emplace_back(desc);
444	      model_data.model_meta.output_desc_v2.emplace_back(desc);
445	    }
446	  }
447	
448	  (void)json_file.Get("dynamic_output_shape", model_data.model_meta.dynamic_output_shape);
449	  (void)json_file.Get("dynamic_batch_info", model_data.model_meta.dynamic_batch_info);
450	  (void)json_file.Get("user_designate_shape_order", model_data.model_meta.user_designate_shape_order);
451	  (void)json_file.Get("dynamic_type", model_data.model_meta.dynamic_type);
452	  (void)json_file.Get("work_size", model_data.model_meta.work_size);
453	  (void)json_file.Get("zero_copy_size", model_data.model_meta.zero_copy_size);
454	  (void)json_file.Get("name", model_data.model_meta.model_name);
455	  (void)json_file.Get("root_graph_name", model_data.model_meta.root_graph_name);
456	
457	  // 读取 aipp 字段
458	  ge::JsonFile aipp_json;
459	  if (json_file.Get("aipp", aipp_json) && aipp_json.IsValid()) {
460	    const ge::Status aipp_ret =
461	        om2::ParseAippJson(aipp_json, model_data.model_meta.aipp_infos, model_data.model_meta.has_aipp);
462	    if (aipp_ret != ge::SUCCESS) {
463	      GELOGW("[OM2][AIPP] ParseAippJson failed, ret=%u", aipp_ret);
464	    }
465	  }
466	  return ge::SUCCESS;
467	}
