488	ge::Status HandleArchiveEntry(const ge::RAIIZipArchive &archive, const std::string &entry,
489	                              gert::Om2ModelData &model_data) {
490	  if (entry.find("/runtime/") != std::string::npos && IsFileNameEndsWith(entry, ".so")) {
491	    GE_ASSERT_SUCCESS(DeserializeCodegenEntry(archive, entry, model_data));
492	    return ge::SUCCESS;
493	  }
494	  if (entry.find("/debug/") != std::string::npos) {
495	    if (IsFileNameEndsWith(entry, "op_attr.json")) {
496	      GE_ASSERT_SUCCESS(DeserializeOpAttrEntry(archive, entry, model_data));
497	    } else {
498	      const std::string debug_file = ExtractParentDirAndFileName(entry).second;
499	      if ((debug_file.find("ge_visual_") != std::string::npos) && IsFileNameEndsWith(debug_file, ".json")) {
500	        GE_ASSERT_SUCCESS(DeserializeVisualEntry(archive, entry, model_data));
501	      }
502	    }
503	    return ge::SUCCESS;
504	  }
505	  if (IsFileNameEndsWith(entry, "model_meta.json")) {
506	    GE_ASSERT_SUCCESS(DeserializeModelMetaEntry(archive, entry, model_data));
507	    return ge::SUCCESS;
508	  }
509	  if (entry.find("data/constants/") != std::string::npos) {
510	    if (IsFileNameEndsWith(entry, "_constants_config.json")) {
511	      GE_ASSERT_SUCCESS(DeserializeConstantsConfigEntry(archive, entry, model_data));
512	    } else if (entry.find("data/constants/constant_") != std::string::npos) {
513	      GE_ASSERT_SUCCESS(DeserializeWeightEntry(archive, entry, model_data));
514	    }
515	    return ge::SUCCESS;
516	  }
517	  if (entry.find("data/variables/") != std::string::npos) {
518	    if (IsFileNameEndsWith(entry, "var_resource.json")) {
519	      GE_ASSERT_SUCCESS(DeserializeVarResourceEntry(archive, entry, model_data));
520	    } else if (IsFileNameEndsWith(entry, "_variables_config.json")) {
521	      GE_ASSERT_SUCCESS(DeserializeVariablesConfigEntry(archive, entry, model_data));
522	    }
523	    return ge::SUCCESS;
524	  }
525	  if (entry.find("data/kernels_") != std::string::npos && IsFileNameEndsWith(entry, ".o")) {
526	    GE_ASSERT_SUCCESS(DeserializeKernelEntry(archive, entry, model_data));
527	  }
528	  return ge::SUCCESS;
529	}
