697	ge::Status ClassifyConstItems(const std::vector<Om2ConstItem> &const_items, ClassifiedConstItems &classified_items) {
698	  classified_items = ClassifiedConstItems();
699	  for (const auto &const_item : const_items) {
700	    classified_items.max_index = std::max(classified_items.max_index, const_item.index);
701	    if (const_item.type == "INTERNAL") {
702	      classified_items.internal_consts.emplace_back(const_item);
703	      continue;
704	    }
705	    if (const_item.type == "COMBINED") {
706	      classified_items.combined_consts.emplace_back(const_item);
707	      continue;
708	    }
709	    if (const_item.type == "INDIVIDUAL") {
710	      classified_items.individual_consts.emplace_back(const_item);
711	      continue;
712	    }
713	    GELOGE(ge::FAILED, "[OM2][Check] Unsupported const type, type=%s", const_item.type.c_str());
714	    return ge::FAILED;
715	  }
716	  return ge::SUCCESS;
717	}
