719	ge::Status ValidateVarMetas(const std::vector<ge::Om2VarMeta> &var_metas) {
720	  if (var_metas.empty()) {
721	    return ge::SUCCESS;
722	  }
723	  const size_t n = var_metas.size();
724	  std::unordered_set<size_t> seen_indices;
725	  seen_indices.reserve(n);
726	  for (const auto &meta : var_metas) {
727	    if (meta.index >= n) {
728	      GELOGE(ge::PARAM_INVALID, "[OM2][Var][Validate] var_meta index %zu out of range [0, %zu), var_name=%s.",
729	             meta.index, n, meta.var_name.c_str());
730	      return ge::PARAM_INVALID;
731	    }
732	    if (!seen_indices.insert(meta.index).second) {
733	      GELOGE(ge::PARAM_INVALID, "[OM2][Var][Validate] duplicate var_meta index %zu, var_name=%s.", meta.index,
734	             meta.var_name.c_str());
735	      return ge::PARAM_INVALID;
736	    }
737	  }
738	  return ge::SUCCESS;
739	}
