777	    run_model_info_.root_graph_name = meta.root_graph_name.empty() ? meta.model_name : meta.root_graph_name;
778	    model_meta_info_.work_size = meta.work_size;
779	    GE_ASSERT_TRUE(meta.zero_copy_size >= 0, "[OM2][Check] Invalid zero_copy_size=%ld.", meta.zero_copy_size);
780	    const auto zero_copy_size = static_cast<size_t>(meta.zero_copy_size);
781	    GE_ASSERT_TRUE(zero_copy_size <= meta.work_size,
782	                   "[OM2][Check] zero_copy_size exceeds work_size, zero_copy_size=%zu, work_size=%zu.", zero_copy_size,
783	                   meta.work_size);
784	    model_meta_info_.zero_copy_size = zero_copy_size;
785	    model_meta_info_.dynamic_batch_info = meta.dynamic_batch_info;
786	    model_meta_info_.dynamic_type = meta.dynamic_type;
