790	    model_meta_info_.input_desc_v2 = meta.input_desc_v2;
791	    model_meta_info_.origin_input_dims = meta.origin_input_dims;
792	    model_meta_info_.output_desc = meta.output_desc;
793	    model_meta_info_.output_desc_v2 = meta.output_desc_v2;
