798	
799	  ge::Status BuildKernelBinInfoFromStruct(const std::vector<gert::Om2KernelBinary> &kernels,
800	                                          std::vector<KernelBinInfo> &info) {
801	    info.clear();
802	    for (const auto &k : kernels) {
803	      KernelBinInfo bin_info;
804	      bin_info.file = k.name;
805	      // 创建非拥有引用：指向 Om2KernelBinary::data (vector<uint8_t>) 的内部缓冲区。
806	      // 生命周期约束：调用方必须保证 Om2ModelData 在 kernel 二进制使用期间保持存活。
807	      // 当前调用链：LoadOm2Graph → Om2ModelManager::LoadModel → executor->Load(model_data, ...)
808	      // 其中 model_data 通过 const & 传递，指向 GeRootModel 持有的 shared_ptr<Om2ModelData>，
809	      // 因此只要 GeRootModel 存活（通常在整个 Session 生命周期内），数据就安全。
810	      if (!k.data.empty()) {
811	        bin_info.data = ge::ReadonlyByteBuffer(k.data.data(), ge::ConditionalDeleter{false});
812	        bin_info.data_size = k.data.size();
813	      } else {
814	        bin_info.data_size = 0U;
815	      }
816	      info.push_back(std::move(bin_info));
817	    }
818	    return ge::SUCCESS;
819	  }
