901	  ge::Status CreateModelFromStruct(const gert::Om2ModelData &model_data, ge::ReadonlyByteBuffer &weight_buf,
902	                                   std::vector<KernelBinInfo> &kernel_bin_info, const Om2ModelLoadArg &load_arg,
903	                                   uint64_t session_id, std::vector<void *> &constants,
904	                                   std::vector<void *> &var_addrs) {
905	    GE_ASSERT_TRUE(has_model_);
906	    GE_ASSERT_TRUE(load_arg.device_id >= 0, "[OM2][Check] Invalid device id.");
907	    device_id_ = load_arg.device_id;
908	    std::vector<const char *> bin_files(kernel_bin_info.size());
909	    std::vector<const void *> bin_data(kernel_bin_info.size());
910	    std::vector<size_t> bin_sizes(kernel_bin_info.size());
911	    void *work_ptr = nullptr;
912	    for (auto i = 0U; i < kernel_bin_info.size(); ++i) {
913	      bin_files[i] = kernel_bin_info[i].file.c_str();
914	      bin_data[i] = kernel_bin_info[i].data.get();
915	      bin_sizes[i] = kernel_bin_info[i].data_size;
916	    }
917	    session_id_ = session_id;
918	    GE_ASSERT_SUCCESS(PrepareWorkPtr(load_arg, work_ptr));
919	    GE_ASSERT_SUCCESS(PrepareConstantsFromStruct(model_data.constants_data, weight_buf, load_arg, constants));
920	    if (model_data.rt_var_resource != nullptr) {
921	      auto var_manager = Om2RTVarManagerPool::Instance().GetManager(session_id);
922	      GE_ASSERT_NOTNULL(var_manager);
923	      GE_ASSERT_SUCCESS(var_manager->Init(*model_data.rt_var_resource));
924	
925	      std::vector<std::string> var_names;
926	      for (const auto &meta : model_data.var_metas) {
927	        var_names.push_back(meta.var_name);
928	      }
929	      GE_ASSERT_SUCCESS(
930	          var_manager->TransAllVarData(var_names, static_cast<uint32_t>(load_arg.device_id), model_data.graph_id));
931	      GE_ASSERT_SUCCESS(var_manager->CopyVarData(var_names, static_cast<uint32_t>(load_arg.device_id)));
932	    }
933	
934	    GE_ASSERT_SUCCESS(PrepareVarAddrs(model_data, static_cast<uint32_t>(load_arg.device_id), var_addrs));
935	    GE_ASSERT_SUCCESS(run_model_info_.create_func(
936	        &run_model_info_.model_handle, &run_model_info_.rt_model_handle, bin_files.data(), bin_data.data(),
937	        bin_sizes.data(), static_cast<int>(bin_data.size()), constants.empty() ? nullptr : constants.data(),
938	        var_addrs.empty() ? nullptr : var_addrs.data(), work_ptr, &session_id_, load_arg.model_id,
939	        dump_manager_.get()));
940	    return ge::GRAPH_SUCCESS;
941	  }
