1038	        (dump_manager_ != nullptr && dump_manager_->IsProfilingEnabled()) ? &prof_info : nullptr;
1039	    GE_ASSERT_SUCCESS(run_model_info_.run_func(&run_model_info_.model_handle, inputs.size(),
1040	                                               reinterpret_cast<void **>(inputs.data()), outputs.size(),
1041	                                               reinterpret_cast<void **>(outputs.data()), timeout, prof_info_ptr));
1042	    if (prof_info_ptr != nullptr) {
1043	      GELOGD("[OM2][Prof] Run done, model_id=%u, prof_count=%u, step_id=%lu", model_id_, prof_info.count, step_id_);
1044	      dump_manager_->ReportModelLevelProf(prof_info);
1045	    } else {
1046	      GELOGD("[OM2][Prof] Run skip, dump_manager is null or profiling disabled, model_id=%u", model_id_);
1047	    }
1048	    ++step_id_;
