1136	  ge::Status SetDynamicSize(const std::vector<uint64_t> &batch_num, const int32_t dynamic_type) {
1137	    GE_ASSERT_TRUE(has_model_);
1138	
1139	    int32_t model_dynamic_type = static_cast<int32_t>(ge::FIXED);
1140	    std::vector<std::vector<int64_t>> dynamic_batch_info;
1141	    ge::Status ret = GetDynamicBatchInfo(dynamic_batch_info, model_dynamic_type);
1142	    if (ret != ge::SUCCESS) {
1143	      GELOGE(ge::FAILED, "[OM2][SetDynamicSize] GetDynamicBatchInfo failed, ret=%u.", ret);
1144	      return ge::FAILED;
1145	    }
1146	
1147	    if (dynamic_type != model_dynamic_type) {
1148	      GELOGE(ge::FAILED, "[OM2][SetDynamicSize] dynamic_type mismatch: requested %d, model compiled with %d.",
1149	             dynamic_type, model_dynamic_type);
1150	      return ge::FAILED;
1151	    }
1152	
1153	    std::vector<int64_t> requested_gear;
1154	    requested_gear.reserve(batch_num.size());
1155	    for (const auto v : batch_num) {
1156	      requested_gear.push_back(static_cast<int64_t>(v));
1157	    }
1158	
1159	    bool gear_found = false;
1160	    for (const auto &gear : dynamic_batch_info) {
1161	      if (gear == requested_gear) {
1162	        gear_found = true;
1163	        break;
1164	      }
1165	    }
1166	
1167	    if (!gear_found) {
1168	      GELOGE(ge::FAILED, "[OM2][SetDynamicSize] Requested gear not found in dynamic_batch_info.");
1169	      return ge::FAILED;
1170	    }
1171	
1172	    cur_batch_size_ = batch_num;
1173	    dynamic_type_ = dynamic_type;
1174	    GELOGI("[OM2][SetDynamicSize] Set dynamic size success, type=%d, size=%zu.", dynamic_type_, cur_batch_size_.size());
1175	    return ge::SUCCESS;
1176	  }
