1257	  ge::Status SetDynamicAippData(void *dynamic_input_addr, const uint64_t length,
1258	                                const std::vector<kAippDynamicBatchPara> &aipp_batch_para,
1259	                                const kAippDynamicPara &aipp_parms) {
1260	    if (dynamic_input_addr == nullptr) {
1261	      REPORT_INNER_ERR_MSG("E19999", "Param dynamic_input_addr is nullptr, check invalid");
1262	      GELOGE(ACL_ERROR_GE_DYNAMIC_INPUT_ADDR_INVALID, "[Check][Param] Dynamic aipp input addr is nullptr");
1263	      return ACL_ERROR_GE_DYNAMIC_INPUT_ADDR_INVALID;
1264	    }
1265	    if (aipp_batch_para.empty()) {
1266	      REPORT_INNER_ERR_MSG("E19999", "Param aipp_batch_para is empty, check invalid");
1267	      GELOGE(ACL_ERROR_GE_AIPP_BATCH_EMPTY, "[Check][Param] aipp_batch_para is empty");
1268	      return ACL_ERROR_GE_AIPP_BATCH_EMPTY;
1269	    }
1270	    const uint64_t batch_num = aipp_batch_para.size();
1271	    constexpr uint64_t real_aipp_params_size = sizeof(kAippDynamicPara) - sizeof(kAippDynamicBatchPara);
1272	    const uint64_t struct_len = (batch_num * sizeof(kAippDynamicBatchPara)) + real_aipp_params_size;
1273	    if (struct_len > length) {
1274	      REPORT_INNER_ERR_MSG("E19999", "input dynamic aipp param len:%" PRIu64 " is larger than aipp_data size:%" PRIu64,
1275	                           struct_len, length);
1276	      GELOGE(ACL_ERROR_GE_DYNAMIC_INPUT_LENGTH_INVALID,
1277	             "[Check][Param] input dynamic aipp param len [%" PRIu64 "] is larger than aipp_data size [%" PRIu64 "]",
1278	             struct_len, length);
1279	      return ACL_ERROR_GE_DYNAMIC_INPUT_LENGTH_INVALID;
1280	    }
1281	    aclError rt_ret =
1282	        aclrtMemcpy(dynamic_input_addr, length, &aipp_parms, real_aipp_params_size, ACL_MEMCPY_HOST_TO_DEVICE);
1283	    if (rt_ret != ACL_SUCCESS) {
1284	      REPORT_INNER_ERR_MSG("E19999", "Call aclrtMemcpy failed, size:%" PRIu64 ", ret:%d", length, rt_ret);
1285	      GELOGE(ge::FAILED, "[Call][aclrtMemcpy] memcpy aipp_parms failed! size:%" PRIu64 ", ret:%d", length, rt_ret);
1286	      return ge::FAILED;
1287	    }
1288	    for (uint64_t i = 0U; i < batch_num; ++i) {
1289	      const uint64_t offset = real_aipp_params_size + (i * sizeof(kAippDynamicBatchPara));
1290	      rt_ret = aclrtMemcpy(static_cast<uint8_t *>(dynamic_input_addr) + offset, length - offset, &aipp_batch_para[i],
1291	                           sizeof(kAippDynamicBatchPara), ACL_MEMCPY_HOST_TO_DEVICE);
1292	      if (rt_ret != ACL_SUCCESS) {
1293	        REPORT_INNER_ERR_MSG("E19999", "Call aclrtMemcpy failed, ret:%d", rt_ret);
1294	        GELOGE(ge::FAILED, "[Call][aclrtMemcpy] memcpy kAippDynamicBatchPara input data failed! ret:%d", rt_ret);
1295	        return ge::FAILED;
1296	      }
1297	    }
1298	    return ge::SUCCESS;
1299	  }
