1302	    if (dump_manager_ != nullptr) {
1303	      dump_manager_.reset();
1304	    }
1305	    if (run_model_info_.destroy_func != nullptr && run_model_info_.model_handle != nullptr) {
1306	      const auto destroy_ret = run_model_info_.destroy_func(&run_model_info_.model_handle);
1307	      if (destroy_ret != ge::GRAPH_SUCCESS) {
1308	        GELOGI("[OM2] Resource release issue for so file: %s", run_model_info_.so_file.c_str());
1309	      }
1310	    } else {
1311	      GELOGI("[OM2] Destroy func not found or model not created, so file: %s", run_model_info_.so_file.c_str());
1312	    }
1313	    if (run_model_info_.so_handle != nullptr) {
1314	      if (mmDlclose(run_model_info_.so_handle) != 0) {
1315	        const char_t *error = mmDlerror();
1316	        error = (error == nullptr) ? "" : error;
1317	        GELOGI("[OM2][Dlclose] path = %s, error = %s", run_model_info_.so_file.c_str(), error);
1318	      }
1319	      run_model_info_.so_handle = nullptr;
1320	    }
1321	    CloseMemFd(run_model_info_.so_fd);
1322	    ReleaseOwnedMemory();
1323	  }
