1343	  ge::Status PrepareInternalConsts(const ge::ReadonlyByteBuffer &weight_buf, const Om2ModelLoadArg &load_arg,
1344	                                   const std::vector<Om2ConstItem> &const_items, size_t internal_weight_size,
1345	                                   std::vector<void *> &constants) {
1346	    if (const_items.empty()) {
1347	      return ge::SUCCESS;
1348	    }
1349	    GE_ASSERT_TRUE(weight_buf != nullptr, "[OM2][Check] Missing internal host weight buffer.");
1350	    const void *host_weight_base = weight_buf.get();
1351	    void *device_weight_base = load_arg.weight_ptr;
1352	    if (device_weight_base != nullptr) {
1353	      GE_ASSERT_TRUE(load_arg.weight_size >= internal_weight_size, "[OM2][Check] Invalid external device weight size.");
1354	    } else {
1355	      GE_ASSERT_SUCCESS(RtMallocBuffer(internal_weight_size, device_weight_base));
1356	      if (device_weight_base != nullptr) {
1357	        owned_buffers_.push_back(device_weight_base);
1358	      }
1359	    }
1360	    GE_ASSERT_SUCCESS(RtMemcpyH2D(device_weight_base, internal_weight_size, host_weight_base, internal_weight_size));
1361	    auto *device_weight_bytes = static_cast<uint8_t *>(device_weight_base);
1362	    for (const auto &const_item : const_items) {
1363	      GE_ASSERT_TRUE((const_item.offset + const_item.size) <= internal_weight_size,
1364	                     "[OM2][Check] Invalid INTERNAL const offset or size.");
1365	      constants[const_item.index] = device_weight_bytes + const_item.offset;
1366	    }
1367	    return ge::SUCCESS;
1368	  }
