1554	ge::Status LoadOm2DataFromFile(const std::string &model_path, ge::ModelData &model_data) {
1555	  GELOGI("Begin to load om2 model data from file, path: [%s]", model_path.c_str());
1556	  const std::string file_path = ge::om2::RealPath(model_path.c_str());
1557	  if (file_path.empty()) {
1558	    REPORT_PREDEFINED_ERR_MSG(
1559	        "E13026", std::vector<const char_t *>({"pathname", "reason"}),
1560	        std::vector<const char_t *>({model_path.c_str(), "It is not a real path. Please check your model path."}));
1561	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID,
1562	           "[Call][RealPath] File path is invalid. Please check your text file '%s'.", model_path.c_str());
1563	    return ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID;
1564	  }
1565	
1566	  std::ifstream fs(file_path, std::ios::binary);
1567	  if (!fs.is_open()) {
1568	    std::array<char_t, kMaxErrorStringLen + 1U> err_buf = {};
1569	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), &err_buf[0], kMaxErrorStringLen);
1570	    const std::string reason = ge::FormatErrnoReason(mmGetErrorCode(), err_msg);
1571	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID, "[Open][File]Failed, file %s, error %s", model_path.c_str(), err_msg);
1572	    REPORT_INNER_ERR_MSG("E19999", "Open file %s failed, reason:%s", model_path.c_str(), reason.c_str());
1573	    return ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID;
1574	  }
1575	
1576	  (void)fs.seekg(0, std::ifstream::end);
1577	  const int64_t len = fs.tellg();
1578	  GE_ASSERT_TRUE(len > 1U);
1579	  (void)fs.seekg(0, std::ifstream::beg);
1580	
1581	  auto *buffer = new (std::nothrow) char_t[static_cast<size_t>(len)];
1582	  if (buffer == nullptr) {
1583	    GELOGE(ge::FAILED, "[Alloc][Mem] Failed to alloc memory for om2, size: %lld", len);
1584	    return ge::FAILED;
1585	  }
1586	
1587	  (void)fs.read(buffer, len);
1588	
1589	  model_data.model_data = buffer;
1590	  model_data.model_len = len;
1591	  model_data.om_path = file_path;
1592	  GELOGI("Load om2 model data success, path: %s, size: %zu", model_path.c_str(), static_cast<size_t>(len));
1593	
1594	  return ge::SUCCESS;
1595	}
