1645	  GE_ASSERT_TRUE(archive.IsGood());
1646	  GE_ASSERT_SUCCESS(GetOm2ModelMetadataFromArchive(archive, input_desc, input_desc_v2, output_desc, output_desc_v2));
1647	  return ge::SUCCESS;
1648	}
1649	
1650	ge::Status GetOm2ModelMetadata(const void *model_data, size_t model_size, std::vector<ge::Om2TensorDesc> &input_desc,
1651	                               std::vector<ge::Om2TensorDesc> &input_desc_v2,
1652	                               std::vector<ge::Om2TensorDesc> &output_desc,
1653	                               std::vector<ge::Om2TensorDesc> &output_desc_v2) {
1654	  ge::RAIIZipArchive archive(static_cast<const uint8_t *>(model_data), model_size);
1655	  GE_ASSERT_TRUE(archive.IsGood());
1656	  GE_ASSERT_SUCCESS(GetOm2ModelMetadataFromArchive(archive, input_desc, input_desc_v2, output_desc, output_desc_v2));
1657	  return ge::SUCCESS;
1658	}
1659	
1660	ge::Status IsOm2Model(const void *data, size_t size, bool &is_support) {
1661	  if (data == nullptr) {
1662	    REPORT_PREDEFINED_ERR_MSG("E10001", std::vector<const char *>({"parameter", "value", "reason"}),
1663	                              std::vector<const char *>({"data", "nullptr", "Model data cannot be nullptr."}));
1664	    GELOGE(ACL_ERROR_GE_PARAM_INVALID, "[Check][Param] Invalid om2 model. Model data cannot be nullptr.");
1665	    return ACL_ERROR_GE_PARAM_INVALID;
1666	  }
1667	
1668	  if (size < FILE_MAGIC_HEADER_SIZE) {
1669	    const std::string err_msg =
1670	        "Model data size must be greater than or equal to " + std::to_string(FILE_MAGIC_HEADER_SIZE);
1671	    REPORT_PREDEFINED_ERR_MSG("E10001", std::vector<const char *>({"parameter", "value", "reason"}),
1672	                              std::vector<const char *>({"size", std::to_string(size).c_str(), err_msg.c_str()}));
1673	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_DATA_SIZE_INVALID,
1674	           "[Check][Param] Invalid om2 model. Model data size %zu must be greater than or equal to %zu.", size,
1675	           FILE_MAGIC_HEADER_SIZE);
1676	    return ACL_ERROR_GE_EXEC_MODEL_DATA_SIZE_INVALID;
1677	  }
1678	
1679	  is_support = std::memcmp(data, OM2_MAGIC, FILE_MAGIC_HEADER_SIZE) == 0;
1680	  return ge::SUCCESS;
1681	}
1682	
1683	ge::Status IsOm2Model(const char *file_path, bool &is_support) {
1684	  const std::string real_path = ge::om2::RealPath(file_path);
1685	  if (real_path.empty()) {
1686	    std::array<char_t, kMaxErrorStringLen + 1U> err_buf = {};
1687	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), err_buf.data(), kMaxErrorStringLen);
1688	    std::string reason = ge::FormatErrnoReason(mmGetErrorCode(), err_msg);
1689	    REPORT_PREDEFINED_ERR_MSG("E13000", std::vector<const char *>({"path", "errmsg"}),
1690	                              std::vector<const char *>({file_path, reason.c_str()}));
1691	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID, "[Check][Param]Model file path %s is invalid", file_path);
1692	    return ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID;
1693	  }
1694	
1695	  std::ifstream file(file_path, std::ios::binary);
1696	  if (!file.is_open()) {
1697	    std::array<char_t, kMaxErrorStringLen + 1U> err_buf = {};
1698	    const auto err_msg = mmGetErrorFormatMessage(mmGetErrorCode(), &err_buf[0], kMaxErrorStringLen);
1699	    const std::string reason = ge::FormatErrnoReason(mmGetErrorCode(), err_msg);
1700	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID, "[Open][File]Failed, file %s, error %s", file_path, err_msg);
1701	    REPORT_INNER_ERR_MSG("E19999", "Open file %s failed, reason:%s", file_path, reason.c_str());
1702	    return ACL_ERROR_GE_EXEC_MODEL_PATH_INVALID;
1703	  }
1704	
1705	  (void)file.seekg(0, std::ifstream::end);
1706	  const size_t len = static_cast<size_t>(file.tellg());
1707	  (void)file.seekg(0, std::ifstream::beg);
1708	  if (len < FILE_MAGIC_HEADER_SIZE) {
1709	    const std::string reason = "Invalid om2 file. The model data size " + std::to_string(len) + " is smaller than " +
1710	                               std::to_string(FILE_MAGIC_HEADER_SIZE) + ".";
1711	    (void)REPORT_PREDEFINED_ERR_MSG("E10001", std::vector<const char *>({"parameter", "value", "reason"}),
1712	                                    std::vector<const char *>({"file_path", file_path, reason.c_str()}));
1713	    GELOGE(ACL_ERROR_GE_EXEC_MODEL_DATA_SIZE_INVALID,
1714	           "[Check][Param] Invalid om2 model. Model data size %" PRIu64 " must be greater than or equal to %zu.", len,
1715	           FILE_MAGIC_HEADER_SIZE);
1716	    return ACL_ERROR_GE_EXEC_MODEL_DATA_SIZE_INVALID;
1717	  }
1718	
1719	  uint8_t magic[FILE_MAGIC_HEADER_SIZE] = {};
1720	  file.read(reinterpret_cast<char *>(magic), FILE_MAGIC_HEADER_SIZE);
1721	  const auto read_len = static_cast<size_t>(file.gcount());
1722	
1723	  GE_ASSERT_SUCCESS(IsOm2Model(magic, read_len, is_support));
1724	  return ge::SUCCESS;
1725	}
1726	}  // namespace gert
