51	ge::Status Om2RTVarManager::Init(const RTVarResource &resource, void *external_var_addr, uint64_t external_var_size) {
52	  const std::lock_guard<std::recursive_mutex> lock(mutex_);
53	  external_var_addr_ = external_var_addr;
54	  external_var_size_ = external_var_size;
55	  for (const auto &[var_key, new_entry] : resource.GetAllEntries()) {
56	    if (var_resource_.GetEntry(var_key) != nullptr) {
