64	ge::Status Om2RTVarManager::AllocDevAddr(const RTVarEntry &entry, void *&dev_addr) {
65	  void *new_addr = nullptr;
66	  const auto malloc_ret = Om2Malloc(&new_addr, entry.size, entry.memory_type, 0);
67	  if (malloc_ret != ACL_SUCCESS) {
68	    GELOGE(ge::FAILED, "[OM2][Var][Alloc] aclrtMalloc failed, var=%s, size=%" PRIu64 ", ret=%u.",
69	           entry.var_name.c_str(), entry.size, malloc_ret);
70	    return ge::FAILED;
71	  }
72	  dev_addr = new_addr;
73	  return ge::SUCCESS;
74	}
