88	ge::Status Om2RTVarManager::GetVarDevAddr(const std::string &var_name, uint32_t device_id, void *&dev_addr) {
89	  const auto *entry = var_resource_.GetEntryByName(var_name);
90	  if (entry == nullptr) {
91	    GELOGE(ge::PARAM_INVALID, "[OM2][Var] var_name=%s not found.", var_name.c_str());
92	    return ge::PARAM_INVALID;
93	  }
94	  return GetVarDevAddr(*entry, device_id, dev_addr);
95	}
96	
97	ge::Status Om2RTVarManager::GetVarDevAddr(const RTVarEntry &entry, uint32_t device_id, void *&dev_addr) {
98	  const std::lock_guard<std::recursive_mutex> lock(mutex_);
99	  auto &state = GetOrCreateRuntimeState(entry.var_key);
100	  auto it = state.dev_addrs.find(device_id);
101	  if (it != state.dev_addrs.end()) {
102	    dev_addr = it->second;
103	    return ge::SUCCESS;
104	  }
105	
106	  void *new_addr = nullptr;
107	  if (entry.extern_dev_addr != nullptr) {
108	    new_addr = entry.extern_dev_addr;
109	  } else if (external_var_addr_ != nullptr) {
110	    if (entry.logic_addr < logic_var_base_) {
111	      GELOGE(ge::FAILED, "[OM2][Var][Alloc] logic_addr %" PRIu64 " < base %" PRIu64 " for var=%s.", entry.logic_addr,
112	             logic_var_base_, entry.var_name.c_str());
113	      return ge::FAILED;
114	    }
115	    const uint64_t offset = entry.logic_addr - logic_var_base_;
116	    if (offset > external_var_size_ || entry.size > (external_var_size_ - offset)) {
117	      GELOGE(ge::FAILED,
118	             "[OM2][Var][Alloc] external arena overflow, var=%s, offset=%" PRIu64 ", size=%" PRIu64 ", arena=%" PRIu64
119	             ".",
120	             entry.var_name.c_str(), offset, entry.size, external_var_size_);
121	      return ge::FAILED;
122	    }
123	    new_addr = static_cast<uint8_t *>(external_var_addr_) + offset;
124	  } else {
125	    GE_RETURN_IF_ERROR(AllocDevAddr(entry, new_addr));
126	  }
127	
128	  state.dev_addrs[device_id] = new_addr;
129	  dev_addr = new_addr;
130	
131	  if (!entry.init_data.empty() && !state.is_loaded[device_id]) {
132	    if (entry.init_data.size() > entry.size) {
133	      GELOGE(ge::FAILED, "[OM2][Var][Alloc] init_data size %zu > entry size %" PRIu64 " for var=%s.",
134	             entry.init_data.size(), entry.size, entry.var_name.c_str());
135	      return ge::FAILED;
136	    }
137	    const auto ret =
138	        aclrtMemcpy(new_addr, entry.size, entry.init_data.data(), entry.init_data.size(), ACL_MEMCPY_HOST_TO_DEVICE);
139	    if (ret != ACL_SUCCESS) {
140	      GELOGE(ge::FAILED, "[OM2][Var][Alloc] init H2D failed, var=%s, ret=%u.", entry.var_name.c_str(), ret);
141	      return ge::FAILED;
142	    }
143	    state.is_loaded[device_id] = true;
144	  }
145	
146	  return ge::SUCCESS;
147	}
