153	void Om2RTVarManager::Finalize() noexcept {
154	  const std::lock_guard<std::recursive_mutex> lock(mutex_);
155	  for (auto &[var_key, state] : var_runtime_states_) {
156	    const auto *entry = var_resource_.GetEntry(var_key);
157	    if (entry == nullptr) {
158	      GELOGW("[OM2][Var][Finalize] var_key=%s not found in var_resource_, skip free.", var_key.c_str());
159	      continue;
160	    }
161	    for (auto &[_, addr] : state.dev_addrs) {
162	      (void)_;
163	      if (addr != nullptr && addr != entry->extern_dev_addr) {
164	        (void)aclrtFree(addr);
165	      }
166	    }
167	  }
168	  var_runtime_states_.clear();
169	  for (auto &[_, vars] : legacy_device_to_vars_) {
170	    (void)_;
171	    for (auto &[__, info] : vars) {
172	      (void)__;
173	      if (info.addr != nullptr) {
174	        (void)aclrtFree(info.addr);
175	      }
176	    }
177	  }
178	  legacy_device_to_vars_.clear();
179	}
180	
181	ge::Status Om2RTVarManager::GetOrCreateVarAddr(const std::string &key, uint32_t device_id, size_t size, void *&addr) {
182	  addr = nullptr;
183	  if (size == 0U) {
184	    return ge::SUCCESS;
185	  }
186	  {
187	    const std::lock_guard<std::recursive_mutex> lock(mutex_);
188	    auto dev_it = legacy_device_to_vars_.find(device_id);
189	    if (dev_it != legacy_device_to_vars_.end()) {
190	      auto var_it = dev_it->second.find(key);
191	      if (var_it != dev_it->second.end()) {
192	        if (var_it->second.size != size) {
193	          GELOGE(ge::FAILED, "[OM2][Var][Legacy] size mismatch for key=%s, cached=%zu, requested=%zu.", key.c_str(),
194	                 var_it->second.size, size);
195	          return ge::FAILED;
196	        }
197	        addr = var_it->second.addr;
198	        return ge::SUCCESS;
199	      }
200	    }
201	  }
202	  void *new_addr = nullptr;
203	  const auto malloc_ret = Om2Malloc(&new_addr, size, RT_MEMORY_HBM, 0);
204	  if (malloc_ret != ACL_SUCCESS) {
205	    GELOGE(ge::FAILED, "[OM2][Var][Alloc] legacy malloc failed, key=%s, size=%zu.", key.c_str(), size);
206	    return ge::FAILED;
207	  }
208	  {
209	    const std::lock_guard<std::recursive_mutex> lock(mutex_);
210	    auto &dev_vars = legacy_device_to_vars_[device_id];
211	    auto var_it = dev_vars.find(key);
212	    if (var_it != dev_vars.end()) {
213	      if (var_it->second.size != size) {
214	        (void)aclrtFree(new_addr);
215	        GELOGE(ge::FAILED, "[OM2][Var][Legacy] size mismatch for key=%s, cached=%zu, requested=%zu.", key.c_str(),
216	               var_it->second.size, size);
217	        return ge::FAILED;
218	      }
219	      addr = var_it->second.addr;
220	      (void)aclrtFree(new_addr);
221	      return ge::SUCCESS;
222	    }
223	    dev_vars[key] = LegacyVarAddrInfo{new_addr, size};
224	    addr = new_addr;
225	  }
226	  return ge::SUCCESS;
227	}
228	
229	bool Om2RTVarManager::TryGetVarAddr(const std::string &key, uint32_t device_id, void *&addr) const {
230	  const std::lock_guard<std::recursive_mutex> lock(mutex_);
231	  addr = nullptr;
232	  auto dev_it = legacy_device_to_vars_.find(device_id);
233	  if (dev_it == legacy_device_to_vars_.end()) {
234	    return false;
235	  }
236	  auto var_it = dev_it->second.find(key);
237	  if (var_it == dev_it->second.end()) {
238	    return false;
239	  }
240	  addr = var_it->second.addr;
241	  return addr != nullptr;
242	}
243	
244	ge::Status Om2RTVarManager::CopyVarFromDevice(const RTVarEntry &entry, const RTVarRuntimeState &state,
245	                                              uint32_t device_id, std::vector<uint8_t> &host_buf) {
246	  auto it = state.dev_addrs.find(device_id);
247	  if (it == state.dev_addrs.end() || it->second == nullptr) {
248	    GELOGE(ge::FAILED, "[OM2][Var] dev_addr not allocated for var=%s, device=%u.", entry.var_name.c_str(), device_id);
249	    return ge::FAILED;
250	  }
251	  host_buf.resize(entry.size);
252	  const auto ret = aclrtMemcpy(host_buf.data(), entry.size, it->second, entry.size, ACL_MEMCPY_DEVICE_TO_HOST);
253	  if (ret != ACL_SUCCESS) {
254	    GELOGE(ge::FAILED, "[OM2][Var][D2H] aclrtMemcpy failed, var=%s, ret=%u.", entry.var_name.c_str(), ret);
255	    return ge::FAILED;
256	  }
257	  return ge::SUCCESS;
258	}
259	
260	ge::Status Om2RTVarManager::CopyVarToDevice(const RTVarEntry &entry, const RTVarRuntimeState &state, uint32_t device_id,
261	                                            const std::vector<uint8_t> &host_buf) {
262	  auto it = state.dev_addrs.find(device_id);
263	  if (it == state.dev_addrs.end() || it->second == nullptr) {
264	    GELOGE(ge::FAILED, "[OM2][Var] dev_addr not allocated for var=%s, device=%u.", entry.var_name.c_str(), device_id);
265	    return ge::FAILED;
266	  }
267	  const auto ret = aclrtMemcpy(it->second, entry.size, host_buf.data(), host_buf.size(), ACL_MEMCPY_HOST_TO_DEVICE);
268	  if (ret != ACL_SUCCESS) {
269	    GELOGE(ge::FAILED, "[OM2][Var][H2D] aclrtMemcpy failed, var=%s, ret=%u.", entry.var_name.c_str(), ret);
270	    return ge::FAILED;
271	  }
272	  return ge::SUCCESS;
273	}
274	
275	ge::Status Om2RTVarManager::TransVarOnHost(const RTVarTransRoad &trans_road, std::vector<uint8_t> &data) {
276	  ge::formats::TransResult last_result{};
277	  bool use_init_data = true;
278	  for (const auto &node : trans_road) {
279	    if (IsNoNeedTrans(node.node_type)) {
280	      continue;
281	    }
282	    uint8_t *src_data = nullptr;
283	    if (use_init_data) {
284	      src_data = data.data();
285	      use_init_data = false;
286	    } else {
287	      src_data = last_result.data.get();
288	    }
289	
290	    ge::formats::TransResult tmp_result{};
291	    if (node.node_type == "TRANSDATA" || node.node_type == "TRANSPOSED") {
292	      const auto src_format = node.input.GetFormat();
293	      const auto dst_format = node.output.GetFormat();
294	      const auto src_shape = node.input.GetShape();
295	      const auto dst_shape = node.output.GetShape();
296	      const auto data_type = node.input.GetDataType();
297	      const ge::Format src_primary = static_cast<ge::Format>(ge::GetPrimaryFormat(static_cast<int32_t>(src_format)));
298	      const ge::Format dst_primary = static_cast<ge::Format>(ge::GetPrimaryFormat(static_cast<int32_t>(dst_format)));
299	      const ge::Format src_sub = static_cast<ge::Format>(ge::GetSubFormat(static_cast<int32_t>(src_format)));
300	      const ge::Format dst_sub = static_cast<ge::Format>(ge::GetSubFormat(static_cast<int32_t>(dst_format)));
301	      const int64_t src_c0 = ge::GetC0Value(static_cast<int32_t>(src_format));
302	      const int64_t dst_c0 = ge::GetC0Value(static_cast<int32_t>(dst_format));
303	      const auto ret = ge::formats::TransDataFormat({src_data, src_format, dst_format, src_primary, dst_primary,
304	                                                     src_sub, dst_sub, src_c0, dst_c0, src_shape, dst_shape, data_type},
305	                                                    tmp_result);
306	      if (ret != ge::SUCCESS) {
307	        GELOGE(ge::FAILED, "[OM2][Var][Trans] TransDataFormat failed, %s, dst_format=%d, ret=%u.",
308	               node.node_type.c_str(), static_cast<int>(dst_format), ret);
309	        return ret;
310	      }
311	    } else if (node.node_type == "CAST") {
312	      const auto &src_shape = node.input.GetShape();
313	      int64_t element_count = 1;
314	      for (const auto dim : src_shape) {
315	        element_count *= dim;
316	      }
317	      if (element_count == 0) {
318	        element_count = 1;
319	      }
320	      const auto src_dtype = node.input.GetDataType();
321	      const auto dst_dtype = node.output.GetDataType();
322	      const auto ret = ge::formats::TransTensorDataType(
323	          {src_data, static_cast<size_t>(element_count), src_dtype, dst_dtype}, tmp_result);
324	      if (ret != ge::SUCCESS) {
325	        GELOGE(ge::FAILED, "[OM2][Var][Trans] TransTensorDataType failed, ret=%u.", ret);
326	        return ret;
327	      }
328	    } else {
329	      GELOGE(ge::UNSUPPORTED, "[OM2][Var][Trans] unsupported node_type=%s.", node.node_type.c_str());
330	      return ge::UNSUPPORTED;
331	    }
332	    last_result = tmp_result;
333	  }
334	
335	  if (last_result.data != nullptr && last_result.length > 0U) {
336	    data.assign(last_result.data.get(), last_result.data.get() + last_result.length);
337	  }
338	  return ge::SUCCESS;
339	}
340	
341	ge::Status Om2RTVarManager::TransSingleVarData(const std::string &var_name, uint32_t device_id) {
342	  const auto *entry = var_resource_.GetEntryByName(var_name);
343	  if (entry == nullptr) {
344	    return ge::FAILED;
345	  }
346	
347	  const auto &input_desc = entry->trans_road.front().input;
348	  const std::string old_var_key = RTVarResource::BuildVarKey(var_name, input_desc);
349	  const auto *old_entry = var_resource_.GetEntry(old_var_key);
350	  if (old_entry == nullptr) {
351	    GELOGW("[OM2][Var][Trans] old entry not found for var=%s, key=%s.", var_name.c_str(), old_var_key.c_str());
352	    return ge::FAILED;
353	  }
354	
355	  void *old_dev_addr = nullptr;
356	  GE_RETURN_IF_ERROR(GetVarDevAddr(*old_entry, device_id, old_dev_addr));
357	
358	  const auto *old_state = GetRuntimeState(old_entry->var_key);
359	  if (old_state == nullptr) {
360	    GELOGE(ge::FAILED, "[OM2][Var][Trans] old state not found for var=%s.", var_name.c_str());
361	    return ge::FAILED;
362	  }
363	
364	  std::vector<uint8_t> host_buf;
365	  GE_RETURN_IF_ERROR(CopyVarFromDevice(*old_entry, *old_state, device_id, host_buf));
366	  GE_RETURN_IF_ERROR(TransVarOnHost(entry->trans_road, host_buf));
367	
368	  void *new_dev_addr = nullptr;
369	  GE_RETURN_IF_ERROR(GetVarDevAddr(*entry, device_id, new_dev_addr));
370	
371	  auto &new_state = GetOrCreateRuntimeState(entry->var_key);
372	  GE_RETURN_IF_ERROR(CopyVarToDevice(*entry, new_state, device_id, host_buf));
373	
374	  new_state.is_loaded[device_id] = true;
375	  GELOGI("[OM2][Var][Trans] var=%s trans completed on device=%u.", var_name.c_str(), device_id);
376	  return ge::SUCCESS;
377	}
378	
379	ge::Status Om2RTVarManager::TransAllVarData(const std::vector<std::string> &var_names, uint32_t device_id,
380	                                            uint32_t graph_id) {
381	  if (var_names.empty()) {
382	    return ge::SUCCESS;
383	  }
384	
385	  std::vector<std::string> vars_to_trans;
386	  for (const auto &var_name : var_names) {
387	    const auto *entry = var_resource_.GetEntryByName(var_name);
388	    if (entry == nullptr || entry->trans_road.empty()) {
389	      continue;
390	    }
391	    if (entry->changed_graph_id != graph_id || entry->changed_graph_id == entry->allocated_graph_id) {
392	      continue;
393	    }
394	    const auto *state = GetRuntimeState(entry->var_key);
395	    if (state != nullptr) {
396	      auto loaded_it = state->is_loaded.find(device_id);
397	      if (loaded_it != state->is_loaded.end() && loaded_it->second) {
398	        continue;
399	      }
400	    }
401	    if (!NeedRealTrans(entry->trans_road)) {
402	      continue;
403	    }
404	    vars_to_trans.push_back(var_name);
405	  }
406	
407	  if (vars_to_trans.empty()) {
408	    return ge::SUCCESS;
409	  }
410	
411	  aclrtContext context = nullptr;
412	  if (aclrtGetCurrentContext(&context) != ACL_SUCCESS) {
413	    GELOGE(ge::FAILED, "[OM2][Var][Trans] get current context failed.");
414	    return ge::FAILED;
415	  }
416	
417	  ge::om2::ThreadPool executor("om2_vartrans", kDefaultVarTransThreadNum);
418	  std::vector<std::future<ge::Status>> futures;
419	
420	  for (const auto &var_name : vars_to_trans) {
421	    auto trans_func = [this, var_name, device_id, context]() -> ge::Status {
422	      if (aclrtSetCurrentContext(context) != ACL_SUCCESS) {
423	        GELOGE(ge::FAILED, "[OM2][Var][Trans] set context failed for var=%s.", var_name.c_str());
424	        return ge::FAILED;
425	      }
426	      return TransSingleVarData(var_name, device_id);
427	    };
428	    auto f = executor.commit(trans_func);
429	    if (!f.valid()) {
430	      GELOGE(ge::FAILED, "[OM2][Var][Trans] commit task failed for var=%s.", var_name.c_str());
431	      return ge::FAILED;
432	    }
433	    futures.push_back(std::move(f));
434	  }
435	
436	  for (auto &f : futures) {
437	    const auto ret = f.get();
438	    if (ret != ge::SUCCESS) {
439	      return ret;
440	    }
441	  }
442	
443	  return ge::SUCCESS;
444	}
445	
446	ge::Status Om2RTVarManager::CopyVarData(const std::vector<std::string> &var_names, uint32_t device_id) {
447	  for (const auto &var_name : var_names) {
448	    const auto *entry = var_resource_.GetEntryByName(var_name);
449	    if (entry == nullptr) {
450	      continue;
451	    }
452	    if (entry->copy_info.src_var_name.empty()) {
453	      continue;
454	    }
455	    const auto *dst_state = GetRuntimeState(entry->var_key);
456	    if (dst_state != nullptr) {
457	      auto loaded_it = dst_state->is_loaded.find(device_id);
458	      if (loaded_it != dst_state->is_loaded.end() && loaded_it->second) {
459	        continue;
460	      }
461	    }
462	
463	    const std::string src_var_key =
464	        RTVarResource::BuildVarKey(entry->copy_info.src_var_name, entry->copy_info.src_tensor_desc);
465	    const auto *src_entry = var_resource_.GetEntry(src_var_key);
466	    if (src_entry == nullptr) {
467	      GELOGW("[OM2][Var][Copy] src entry not found, var=%s, src_key=%s.", var_name.c_str(), src_var_key.c_str());
468	      continue;
469	    }
470	
471	    void *src_addr = nullptr;
472	    GE_RETURN_IF_ERROR(GetVarDevAddr(*src_entry, device_id, src_addr));
473	
474	    const auto *src_state = GetRuntimeState(src_entry->var_key);
475	    if (src_state == nullptr) {
476	      GELOGE(ge::FAILED, "[OM2][Var][Copy] src state not found, var=%s.", var_name.c_str());
477	      return ge::FAILED;
478	    }
479	
480	    std::vector<uint8_t> host_buf;
481	    GE_RETURN_IF_ERROR(CopyVarFromDevice(*src_entry, *src_state, device_id, host_buf));
482	
483	    if (src_entry->tensor_desc.GetDataType() != entry->tensor_desc.GetDataType()) {
484	      int64_t element_count = 1;
485	      for (const auto dim : src_entry->tensor_desc.GetShape()) {
486	        element_count *= dim;
487	      }
488	      if (element_count == 0) {
489	        element_count = 1;
490	      }
491	      ge::formats::TransResult cast_result{};
492	      const auto cast_ret =
493	          ge::formats::TransTensorDataType({host_buf.data(), static_cast<size_t>(element_count),
494	                                            src_entry->tensor_desc.GetDataType(), entry->tensor_desc.GetDataType()},
495	                                           cast_result);
496	      if (cast_ret != ge::SUCCESS) {
497	        GELOGE(ge::FAILED, "[OM2][Var][Copy] dtype cast failed, var=%s, ret=%u.", var_name.c_str(), cast_ret);
498	        return cast_ret;
499	      }
500	      host_buf.assign(cast_result.data.get(), cast_result.data.get() + cast_result.length);
501	    }
502	
503	    void *dst_addr = nullptr;
504	    GE_RETURN_IF_ERROR(GetVarDevAddr(*entry, device_id, dst_addr));
505	
506	    auto &new_dst_state = GetOrCreateRuntimeState(entry->var_key);
507	    GE_RETURN_IF_ERROR(CopyVarToDevice(*entry, new_dst_state, device_id, host_buf));
508	
509	    new_dst_state.is_loaded[device_id] = true;
510	    GELOGI("[OM2][Var][Copy] var=%s copied from src=%s on device=%u.", var_name.c_str(),
511	           entry->copy_info.src_var_name.c_str(), device_id);
512	  }
513	  return ge::SUCCESS;
514	}
515	
516	Om2RTVarManagerPool &Om2RTVarManagerPool::Instance() {
517	  static Om2RTVarManagerPool pool;
518	  return pool;
519	}
