525	Om2RTVarManagerPtr Om2RTVarManagerPool::GetManager(uint64_t session_id) {
526	  const std::lock_guard<std::mutex> lock(mutex_);
527	  auto &manager = session_id_to_manager_[session_id];
528	  if (manager == nullptr) {
529	    manager = std::make_shared<Om2RTVarManager>();
530	    if (manager == nullptr) {
531	      GELOGE(ge::INTERNAL_ERROR, "[OM2][New][RTVarManager] failed, session_id=%" PRIu64 ".", session_id);
532	      return nullptr;
533	    }
534	  }
535	  return manager;
536	}
537	
538	void Om2RTVarManagerPool::RemoveManager(uint64_t session_id) {
539	  Om2RTVarManagerPtr manager = nullptr;
540	  {
541	    const std::lock_guard<std::mutex> lock(mutex_);
542	    auto it = session_id_to_manager_.find(session_id);
543	    if (it != session_id_to_manager_.end()) {
544	      manager = it->second;
545	      (void)session_id_to_manager_.erase(it);
546	    }
547	  }
548	  if (manager != nullptr) {
549	    manager->Finalize();
550	  }
551	}
552	
553	void Om2RTVarManagerPool::Destroy() noexcept {
554	  const std::lock_guard<std::mutex> lock(mutex_);
555	  for (const auto &[_, mgr] : session_id_to_manager_) {
556	    (void)_;
557	    if (mgr != nullptr) {
558	      mgr->Finalize();
559	    }
560	  }
561	  session_id_to_manager_.clear();
562	}
