62	struct MemInfo {
63	  int64_t logic_memory_base;
64	  int64_t memory_size;
65	  uint8_t *memory_base;
66	  uint64_t memory_type;
67	  std::string memory_key;
68	  bool is_fixed_addr_prior;
69	  MemInfo() : MemInfo(0, 0, nullptr, false) {}
70	
71	  MemInfo(int64_t logic_memory_base_tmp, int64_t memory_size_tmp, uint8_t *const memory_base_tmp,
72	          bool is_fixed_addr_prior_tmp = false)
73	      : logic_memory_base(logic_memory_base_tmp),
74	        memory_size(memory_size_tmp),
75	        memory_base(memory_base_tmp),
76	        memory_type(RT_MEMORY_HBM),
77	        is_fixed_addr_prior(is_fixed_addr_prior_tmp) {}
78	
79	  friend bool operator<(const MemInfo &left, const MemInfo &right) noexcept {
80	    // 加上大小是为了地址段匹配处理，不要擅自修改
81	    // 如logic_memory_base=0, memory_size=100, logic_memory_base=100, memory_size=300
82	    // logic_addr为[0, 100)匹配到的基地址就是logic_memory_base=0
83	    // logic_addr为[100, 400)匹配到的基地址就是logic_memory_base=100
84	    return (left.logic_memory_base + left.memory_size) < (right.logic_memory_base + right.memory_size);
85	  }
