87	  std::string ToString() const {
88	    std::stringstream ss;
89	    ss << "memory_size:" << memory_size << ", logic_memory_base:" << logic_memory_base << ", memory_base:0x"
90	       << &std::hex << PtrToValue(PtrToPtr<uint8_t, void>(memory_base)) << ", memory_type:" << memory_type
91	       << ", memory_key:" << memory_key << ", is_fixed_addr_prior:" << is_fixed_addr_prior;
92	    return ss.str();
93	  }
94	
95	  void *GetMemory(const int64_t offset, const int64_t bytes) const {
96	    if (bytes <= 0) {
97	      return nullptr;
98	    }
99	    GE_CHK_STATUS_EXEC(CheckInt64SubOverflow(offset, logic_memory_base), return nullptr,
100	                       "[Get][Memory] failed,Out of range, total size:%" PRId64 ", offset:%" PRId64
101	                       ", logic_memory_base:%" PRId64 ".",
102	                       memory_size, offset, logic_memory_base);
103	    const int64_t real_offset = offset - logic_memory_base;
104	
105	    GE_CHK_STATUS_EXEC(CheckInt64AddOverflow(real_offset, bytes), return nullptr,
106	                       "[Get][Memory] failed,Out of range, total size:%" PRId64 ", offset:%" PRId64 ", bytes:%" PRId64
107	                       ".",
108	                       memory_size, real_offset, bytes);
109	
110	    if ((real_offset + bytes) <= memory_size) {
111	      return ValueToPtr(PtrToValue(memory_base) + static_cast<uint64_t>(real_offset));
112	    }
113	
114	    REPORT_INNER_ERR_MSG("E19999",
115	                         "Out of range, total size:%" PRId64 ", offset:%" PRId64
116	                         ", bytes:"
117	                         "%" PRId64 ".",
118	                         memory_size, real_offset, bytes);
119	    GELOGE(OUT_OF_MEMORY, "Out of range, total size:%" PRId64 ", offset:%" PRId64 ", bytes:%" PRId64 ".", memory_size,
120	           real_offset, bytes);
121	    return nullptr;
122	  }
